        new() { Id = "change_tone",    Name = "Change Tone",     Icon = "🎭", Shortcut = "",  Description = "Make it professional and polished",          IsBuiltIn = true, Prompt = "You are a professional communications expert. Rewrite the following text in a polished, professional tone suitable for a business or formal context. Use confident, precise language; eliminate slang, contractions, and casual phrasing; and ensure the message is clear and authoritative. Preserve all the original meaning and information. Return only the rewritten text:\n\n{text}" },
        new() { Id = "rewrite",        Name = "Rewrite",         Icon = "↺",  Shortcut = "R", Description = "Rewrite in a cleaner, clearer way",          IsBuiltIn = true, Prompt = "You are an expert writer and editor. Completely rewrite the following text so it is clearer, more coherent, and more compelling. Restructure sentences for better flow, use active voice where appropriate, vary sentence length for rhythm, and choose precise, vivid words over vague ones. Keep the original meaning and intent intact. Return only the rewritten text:\n\n{text}" },
