        new() { Id = "bullet_points",  Name = "Bullet Points",   Icon = "•",  Shortcut = "B", Description = "Convert to bullet points",                  IsBuiltIn = true, Prompt = "You are an expert at structuring information. Convert the following text into a well-organized bullet-point list. Group related ideas under clear headings if the content warrants it. Each bullet should be concise, start with a strong verb or noun, and stand on its own. Preserve all important information — do not omit key details. Return only the bullet points:\n\n{text}" },
        new() { Id = "casual_tone",    Name = "Casual Tone",     Icon = "😊", Shortcut = "",  Description = "Make it casual and friendly",               IsBuiltIn = true, Prompt = "You are a friendly, natural writer. Rewrite the following text in a warm, conversational tone as if talking to a friend. Use natural contractions, everyday vocabulary, a light touch of personality, and short punchy sentences where they help. Keep the full meaning intact — just make it feel human and approachable. Return only the rewritten text:\n\n{text}" },
        new() { Id = "improve",        Name = "Improve Writing", Icon = "⬆",  Shortcut = "I", Description = "Improve clarity, flow, and impact",         IsBuiltIn = true, Prompt = "You are a world-class editor. Improve the following text to the highest standard. Strengthen the opening line so it grabs attention. Improve logical flow and transitions between ideas. Upgrade weak or vague word choices to precise, impactful ones. Vary sentence rhythm to keep the reader engaged. Sharpen the closing for maximum impact. Preserve the author's voice and all original meaning. Return only the improved text:\n\n{text}" },
        new() { Id = "explain_code",   Name = "Explain Code",    Icon = "🖥", Shortcut = "C", Description = "Explain what this code does",               IsBuiltIn = true, Prompt = "You are a senior software engineer and expert technical communicator. Explain the following code clearly and thoroughly. Describe its overall purpose, walk through the key logic step by step, explain any important functions, classes, or variables, and flag any notable patterns, edge cases, or potential pitfalls. Write for a developer who may be unfamiliar with this specific code. Return only the explanation:\n\n{text}" },
