    public List<ActionItem> GetDefaults()
    {
        return Defaults.Select(a => new ActionItem
        {
            Id = a.Id,
            Name = a.Name,
            Description = a.Description,
            Icon = a.Icon,
            Shortcut = a.Shortcut,
            Prompt = a.Prompt,
            IsBuiltIn = true
        }).ToList();
    }
}
